    oracle_groups={'MaintenanceParentGuardTest':['assertEquals(300, guard.remainingNanos())','for (long before : new long[] {500, 501})','for (long after : new long[] {99, 500, 501})','assertEquals(2, reads.get())','assertTrue(Thread.currentThread().isInterrupted())','frame(true).parentsGuard(null, probe)','new UUID(0, 4)']}
